void config_biome(uint32_t i, channels::boundary_biome &g) {
  switch (i) {
    case 0: config_biome_alpine(g); return;
    case 1: config_biome_boreal(g); return;
    case 2: config_biome_desert(g); return;
    case 3: config_biome_mediterranean(g); return;
    case 4: config_biome_temperate(g); return;
    case 5: config_biome_tropical(g); return;
    case 6: config_biome_volcanic(g); return;
  }
}

